        "of harm, such as falsehoods, imperfections, desires, opinions, loss of",
        "time, and many other things which breed many kinds of impurity in the",
        "soul. And it is clear that the soul must of necessity fall into many",
        "perils of falsehood, when it admits knowledge and reasoning; for",
        "oftentimes that which is true must appear false, and that which is",
        "certain, doubtful; and contrariwise; for there is scarcely a single",
