        "forms, kinds of knowledge and reflections, by means whereof he can",
        "taint the soul with pride, avarice, wrath, envy, etc., and cause it",
        "unjust hatred, or vain love, and deceive it in many ways. And besides",
        "this, he is wont to leave impressions, and to implant them in the",
        "fancy, in such wise that those that are false appear true, and those",
        "that are true, false, And finally all the worst deceptions which are",
        "caused by the devil, and the evils that he brings to the soul, enter by",
        "way of knowledge and reflections of the memory, Thus if the memory",
        "enter into darkness with respect to them all, and be annihilated in its",
        "oblivion to them, it shuts the door altogether upon this evil which",
