        "and judgment may form no express conception that God is like any one of",
        "these things, yet the very esteeming of these apprehensions, if in fact",
        "the soul esteems them, makes and causes it not to esteem God, or not to",
        "feel concerning Him, as highly as faith teaches, since faith tells us",
        "that He is incomparable, incomprehensible, and so forth. For, quite",
        "apart from the fact that the soul takes from God all that it gives to",
        "the creature, it is natural that its esteem of these apprehensible",
        "things should lead it to make a certain inward comparison between such",
        "things and God, which would prevent it from judging and esteeming God",
        "as highly as it ought. For the creatures, whether terrestrial or",
        "celestial, and all distinct images and kinds of knowledge, both natural",
        "and supernatural, that can be encompassed by the faculties of the soul,",
        "however lofty they be in this life, have no comparison or proportion",
        "with the Being of God, since God falls within no genus and no species,",
        "whereas the creatures do, or so the theologians tell us. And the soul",
        "in this life is not capable of receiving in a clear and distinct manner",
        "aught save that which falls within genus and species. For this cause",
        "Saint John says that no man hath seen God at any time. And Isaias",
