        "more easily apprehended if we summarize it here. To this end it must be",
        "remembered that, since our aim is the union of the soul with God in",
        "hope, according to the memory, and since that which is hoped for is",
        "that which is not possessed, and since, the less we possess of other",
        "things, the greater scope and the greater capacity have we for hoping,",
        "and consequently the greater hope, therefore, the more things we",
        "possess, the less scope and capacity is there for hoping, and",
        "consequently the less hope have we. Hence, the more the soul",
        "dispossesses the memory of forms and things which may be recalled by",
        "it, which are not God, the more will it set its memory upon God, and",
        "the emptier will its memory become, so that it may hope for Him Who",
        "shall fill it. What must be done, then, that the soul may live in the",
        "perfect and pure hope of God is that, whensoever these distinct images,",
        "forms and ideas come to it, it must not rest in them, but must turn",
        "immediately to God, voiding the memory of them entirely, with loving",
        "affection. It must neither think of these things nor consider them",
        "beyond the degree which is necessary for the understanding and",
        "performing of its obligations, if they have any concern with these. And",
        "this it must do without setting any affection or inclination upon them,",
        "so that they may produce no effects in the soul. And thus a man must",
