        "provided he preserves no affection or attachments, this will do him no",
        "harm. For this matter the lines of the Mount, which are in the",
        "thirteenth chapter of the first book, will be of profit.",
        "2. But here it must be borne in mind that this doctrine ours does not",
        "agree, nor do we desire that it should agree, with the doctrine of",
