        "under any one of these six divisions which I am treating), therefore I",
        "speak under each heading of some evils and benefits which are also",
        "found under another, since these, as I say, are connected with that joy",
        "which belongs to them all. But my principal intent is to speak of the",
        "particular evils and benefits which come to the soul, with respect to",
        "each thing, through its rejoicing or not rejoicing in it. These I call",
        "particular evils, because they are primarily and immediately caused by",
        "one particular kind of rejoicing, and are not, save in a secondary and",
        "mediate sense, caused by another. The evil of spiritual lukewarmness,",
        "for example, is caused directly by any and every kind of joy, and this",
        "evil is therefore common to all these six kinds; but fornication is a",
        "particular evil, which is the direct result only of joy in the good",
        "2. The spiritual and bodily evils, then, which directly and effectively",
        "come to the soul when it sets its rejoicing on the good things of",
        "nature are reduced to six principal evils. The first is vainglory,",
        "presumption, pride and disesteem of our neighbour; for a man cannot",
        "cast eyes of esteem on one thing without taking them from the rest.",
        "From this follows, at the least, a real disesteem for everything else;",
        "for naturally, by setting our esteem on one thing, we withdraw our",
        "heart from all things else and set it upon the thing esteemed; and from",
        "this real contempt it is very easy to fall into an intentional and",
        "voluntary contempt for all these other things, in particular or in",
        "general, not only in the heart, but also in speech, when we say that",
        "such a thing or such a person is not like such another. The second evil",
        "is the moving of the senses to complacency and sensual delight and",
        "lust. The third evil comes from falling into adulation and vain praise,",
        "wherein is deception and vanity, as Isaias says in these words: My",
        "people, he that praises thee deceives thee.' And the reason is",
        "that, although we sometimes speak the truth when we praise grace and",
        "beauty, yet it will be a marvel if there is not some evil enwrapped",
        "therein or if the person praised is not plunged into vain complacency",
        "and rejoicing, or his imperfect intentions and affections are not",
        "directed thereto. The fourth evil is of a general kind: it is a serious",
        "blunting of the reason and the spiritual sense, such as is",
        "effected by rejoicing in temporal good things. In one way, indeed, it",
        "is much worse. For as the good things of nature are more closely",
        "connected with man than are temporal good things, the joy which they",
        "give leaves an impression and effect and trace upon the senses more",
        "readily and more effectively, and deadens them more completely. And",
        "thus reason and judgment are not free, but are clouded with that",
        "affection of joy which is very closely connected with them; and from",
        "this arises the fifth evil, which is distraction of the mind by created"
