        "practice of works of mercy, the keeping of the law of God, and of that",
        "of the commonweal, and the putting into practice of all good",
        "2. These kinds of moral good, when they are possessed and practised,",
        "deserve perhaps more than any of the other kinds aforementioned that",
        "the will should rejoice in them. For a man may rejoice in his own",
        "affairs for one of two reasons, or for both reasons together -- namely,",
        "for that which they are in themselves, or for the good which they imply",
        "and bring with them as a means and instrument. We shall find that the",
        "possession of the three kinds of good already mentioned merits no",
        "rejoicing of the will. For of themselves, as has been said, they do no",
        "good to man, nor in themselves have they any good, since they are so",
        "fleeting and frail; rather, as we have likewise said, they cause and",
        "bring him trouble and grief and affliction of spirit. Now, although",
        "they might merit that man should rejoice in them for the second reason",
        "-- which is that he may profit by them for journeying to God -- this is",
        "so uncertain that, as we commonly see, they more often harm man than",
        "bring him profit. But good things of a moral kind merit a certain",
        "degree of rejoicing in him that possesses them, and this for the first",
        "reason -- namely, for their intrinsic nature and worth. For they bring",
        "with them peace and tranquillity, and a right and ordered use of the",
        "reason and actions that are consistent therewith, so that a man cannot,",
        "humanly speaking, have anything better in this life.",
        "3. Thus, since these virtues deserve to be loved and esteemed, humanly",
