        "and which are true, and how and at what time they should be practised,",
        "much counsel and much light from God are needful, both of which are",
        "greatly impeded by joy in these operations and esteem for them. And",
        "this for two reasons: first, because joy blunts and obscures the",
        "judgment; second, because, when a man has joy in these things, not only",
        "does he the more quickly become eager for them, but he is also the more",
        "impelled to practise them out of the proper season. And even supposing",
