        "them, is the use of extraordinary and supernatural happenings, of which",
        "he gives examples by means of images, both the material and corporeal",
        "images used by the Church, and also those which he is wont to fix in",
        "the fancy in relation to such or such a saint, or an image of him,",
        "transforming himself into an angel of light that he may deceive. For in",
        "those very means which we possess for our relief and help the astute",
