        "in our hearts, there is no better way than to direct the energy of our",
        "prayer to the thing that most pleases God. For then not only will He",
        "give that which we ask of Him, which is salvation, but also that which",
        "He sees to be fitting and good for us, although we pray not for it.",
        "This David makes clear in a psalm where he says: The Lord is nigh unto",
        "those that call upon Him in truth, that beg Him for the things",
        "that are in the highest degree true, such as salvation; for of these he",
        "then says: He will fulfill the will of them that fear Him, and will",
        "hear their cries, and will save them. For God is the guardian of those",
        "that truly love Him.' And thus, this nearness to God of which",
        "David here speaks is naught else than His being ready to satisfy them",
        "and grant them even that which it has not passed through their minds to",
        "ask. Even so we read that, because Solomon did well in asking God for a",
        "thing that was pleasing to Him -- namely, wisdom to lead and rule his",
        "people righteously -- God answered him, saying: Because more than aught",
